window.LULU_PASSAGES={"nile":{"src":"qiyas","text":"تختلف الأنهار فيما بينها اختلافًا كبيرًا من حيث الحجم، فبعضها صغير جدًا حتى إنها تجفّ خلال فصول الجفاف. وأطول نهر في العالم هو نهر النيل في إفريقيا، ويليه من حيث الطول نهر الأمازون في أمريكا الجنوبية، إلا أن كمية المياه التي يحملها نهر الأمازون تفوق كمية المياه في أي نهر آخر، بل وتفوق كمية المياه في نهر النيل، ونهر المسيسيبي في أمريكا، ونهر يانغتسي في الصين، مجتمعة.\nوإلى جانب كون الأنهار مهمة للزراعة، فهي مصدر مهم للطاقة؛ إذ يمكن استخدام قوة تدفق المياه على امتداد النهر، عند المساقط وغيرها من المناطق المنحدرة؛ لتشغيل الآلات، وتوليد الكهرباء، حيث تحوّل السواقي والدواليب المائية قوة المياه المتدفقة إلى طاقة. وكانت الطواحين والورش ومصانع النسيج تقام في الماضي بالقرب من الأنهار المنحدرة، وكانت تديرها قوة اندفاع المياه. وفي الوقت الحاضر، تنتج محطات القوة الكهرومائية، ذات التوربينات المائية، نحو ربع القوة الكهربائية التي يحتاجها العالم."},"brand":{"src":"qiyas","text":"كلما ترسّخ الاسم التجاري في أذهان الناس؛ زاد استهلاك المنتج؛ وبالتالي زادت أرباح الشركة."},"knowledge":{"src":"qiyas","text":"عصرنا عصر انفجار المعرفة؛ فأعداد هائلة من العلماء يشتغلون بالبحث العلمي لاختراع وتطوير وسائل حفظ المعلومات ونقلها وبثّها؛ للدفع قُدُمًا بالتواصل الكوني الفريد. كل ذلك جعل الناس مغمورين بالأخبار والمعلومات والمفاهيم التي ترد إليهم في كل لحظة من شتى أصقاع الأرض."},"sleep":{"src":"original","text":"يظن كثير من الطلاب أن السهر حتى الفجر قبل الاختبار يزيد فرص النجاح، لكن الدراسات تشير إلى عكس ذلك؛ ففي أثناء النوم يعيد الدماغ ترتيب المعلومات التي تعلّمها الإنسان في يومه، وينقل المهم منها إلى الذاكرة طويلة المدى. وحين يُحرم الطالب من النوم يقلّ تركيزه، ويبطؤ تفكيره، ويصبح أكثر عُرضة للأخطاء البسيطة. لذلك ينصح المختصون بنوم كافٍ في الليالي التي تسبق الاختبار، وبمراجعة خفيفة بدل الحفظ المتواصل."},"palm":{"src":"original","text":"النخلة شجرة مباركة عرفها أهل الجزيرة العربية منذ آلاف السنين، وقد استفادوا من كل جزء فيها: فثمرها غذاء، وجذوعها تُستعمل في تسقيف البيوت، وسعفها يُصنع منه الحصير والسلال، وليفها تُفتل منه الحبال. وتتحمّل النخلة الحرارة الشديدة وقلة الماء، ولهذا انتشرت زراعتها في الواحات. وتُعدّ المملكة العربية السعودية اليوم من أكبر الدول المنتجة للتمور في العالم."},"bees":{"src":"original","text":"تعيش النحلة العاملة نحو ستة أسابيع فقط في موسم النشاط، لكنها تقضي هذه المدة القصيرة في عمل متواصل: فهي تنظّف الخلية، وتغذّي اليرقات، وتبني الأقراص الشمعية، ثم تخرج لجمع الرحيق. وتتواصل النحلات فيما بينها برقصات خاصة تدل على مكان الأزهار وبُعدها عن الخلية. والطريف أن النحلة الواحدة لا تنتج طوال حياتها إلا جزءًا صغيرًا من ملعقة عسل؛ فالعسل الذي نأكله ثمرة تعاون آلاف النحلات."},"khwarizmi":{"src":"original","text":"يُعدّ محمد بن موسى الخوارزمي من أبرز علماء الرياضيات في الحضارة الإسلامية، عاش في بغداد في القرن الثالث الهجري، وألّف كتاب «المختصر في حساب الجبر والمقابلة» الذي جعل الجبر علمًا مستقلًا. وقد تُرجم الكتاب إلى اللاتينية فانتقل علمه إلى أوروبا، ومن اسمه اشتُقّت كلمة «خوارزمية» التي تُستخدم اليوم في علوم الحاسب للدلالة على خطوات حل المسألة."},"phone":{"src":"original","text":"أجرى باحثون تجربة طلبوا فيها من مجموعتين من الطلاب حلّ مسائل ذهنية؛ وُضعت هواتف المجموعة الأولى في غرفة أخرى، بينما بقيت هواتف المجموعة الثانية على الطاولة مقلوبة وصامتة. وجاءت نتائج المجموعة الأولى أفضل، مع أن هواتف المجموعة الثانية لم تُصدر أي إشعار. ويفسّر الباحثون ذلك بأن جزءًا من انتباه الدماغ ينشغل بمقاومة الرغبة في تفقّد الهاتف ما دام قريبًا."},"desert":{"src":"original","text":"التصحّر هو تحوّل الأراضي الخصبة تدريجيًا إلى أراضٍ قاحلة، ومن أسبابه الطبيعية قلة الأمطار وارتفاع الحرارة، ومن أسبابه البشرية الرعي الجائر وقطع الأشجار. ولمواجهته تلجأ الدول إلى التشجير، وتنظيم الرعي، وإنشاء مصدّات الرياح. وقد أطلقت المملكة مبادرة «السعودية الخضراء» التي تستهدف زراعة عشرة مليارات شجرة."},"coffee":{"src":"original","text":"تحتل القهوة العربية مكانة خاصة في حياة أهل الجزيرة العربية؛ فهي أول ما يُقدَّم للضيف، ويُعدّ تقديمها علامةً على الترحيب والكرم. ولتقديمها آداب متوارثة: فيمسك المضيف الدلّة بيده اليسرى والفنجان باليمنى، ويبدأ بالضيف الأكبر سنًّا أو الأعلى مكانة، ولا يملأ الفنجان إلى آخره، بل يصبّ فيه قليلًا حتى يبقى ساخنًا ويتكرر الصبّ. ويهزّ الضيف فنجانه إذا اكتفى. وقد أدرجت منظمة اليونسكو القهوة العربية ضمن التراث الثقافي غير المادي للبشرية؛ اعترافًا بقيمتها الاجتماعية."},"plastic":{"src":"original","text":"يصل إلى البحار كل عام ملايين الأطنان من النفايات البلاستيكية، ولا يتحلّل البلاستيك كما تتحلّل بقايا النبات، بل يتفتّت مع الزمن إلى قطع دقيقة تُسمّى «اللدائن الدقيقة». وتظن بعض الكائنات البحرية هذه القطع طعامًا فتبتلعها، فتنتقل عبر السلسلة الغذائية حتى تصل إلى الأسماك التي يأكلها الإنسان. ويرى المختصون أن الحل لا يقتصر على تنظيف الشواطئ، لأن ذلك يعالج النتيجة لا السبب، بل يبدأ من تقليل استخدام البلاستيك ذي الاستعمال الواحد وإعادة تدوير ما يمكن تدويره."},"spacing":{"src":"original","text":"تذاكر كثير من الطالبات الدرس مرة واحدة طويلة قبل الاختبار بليلة، ويشعرن بعدها أنهن أتقنّه، ثم يفاجأن بنسيان أكثره بعد أيام. ويفسّر علماء النفس ذلك بما يسمّونه «منحنى النسيان»؛ إذ يفقد الإنسان جزءًا كبيرًا مما تعلّمه خلال الأيام الأولى إن لم يراجعه. أما المراجعة المتباعدة، أي تقسيم المذاكرة على جلسات قصيرة تفصل بينها أيام، فتجعل الدماغ يسترجع المعلومة كل مرة قبل أن تضيع، فتثبت في الذاكرة مدة أطول، مع أن مجموع وقت المذاكرة قد لا يزيد."},"falcon":{"src":"original","text":"الصقارة هواية عريقة في الجزيرة العربية، كان الآباء يعلّمونها الأبناء جيلًا بعد جيل. ويبدأ الصقّار بتعويد الصقر على صوته ويده، فيغطّي رأسه بالبرقع حتى يهدأ، ثم يدرّبه على العودة إليه بالطُّعم. ويحتاج ذلك إلى صبر طويل؛ فالصقر لا يُطيع بالقسوة، بل بالألفة والثقة. ولم تكن الصقارة قديمًا للتسلية فقط، بل كانت وسيلة لصيد الطعام في الصحراء. وتُقام اليوم مهرجانات تُعرض فيها أجود الصقور، ويُحرص فيها على صيد الطيور بطرق تحمي أنواعها من الانقراض."},"mangrove":{"src":"original","text":"تنمو أشجار القرم (المانغروف) على سواحل البحر الأحمر والخليج العربي، في المياه المالحة التي لا تحتملها أغلب النباتات. وقد تكيّفت معها بطرق عجيبة؛ فبعضها يطرد الملح الزائد من أوراقه، وبعضها يرسل جذورًا تنمو إلى أعلى فوق الطين لتتنفّس. وتُعدّ غابات القرم ملجأً لصغار الأسماك والطيور، كما تحمي الشواطئ من التآكل بتثبيت الطين بجذورها المتشابكة. ولذلك تزرع المملكة ملايين من شتلاتها ضمن جهودها لحماية البيئة الساحلية."},"haytham":{"src":"original","text":"ظل كثير من العلماء القدماء يعتقدون أن العين تُطلق شعاعًا يسقط على الأشياء فنراها، حتى جاء الحسن بن الهيثم في القرن الخامس الهجري فخالفهم، وأثبت بالتجربة أن الرؤية تحدث حين ينعكس الضوء عن الأجسام فيدخل العين. ومن تجاربه أنه أدخل الضوء إلى غرفة مظلمة من ثقب صغير، فظهرت على الجدار المقابل صورة مقلوبة لما في الخارج. ولم يكتفِ ابن الهيثم بالتأمل كما فعل كثير ممن سبقوه، بل كان يختبر كل فكرة بالتجربة؛ ولهذا يعدّه المؤرخون من روّاد المنهج العلمي."},"procrastination":{"src":"original","text":"التسويف هو تأجيل المهمة مع العلم بأن تأجيلها يضرّ. ولا يرجع دائمًا إلى الكسل كما يظن الناس؛ فكثيرًا ما يؤجّل الإنسان المهمة لأنها تبدو كبيرة مخيفة، أو لأنه يخشى ألا يؤديها على أكمل وجه. ومن أنجح طرق علاجه تقسيم المهمة الكبيرة إلى خطوات صغيرة جدًا، والبدء بأسهلها خمس دقائق فقط؛ فالبداية الصغيرة تكسر رهبة المهمة، وكثيرًا ما يستمر الإنسان بعدها أكثر مما خطّط. كما يساعد إبعاد المشتّتات وتحديد وقت واضح لكل خطوة."},"camel":{"src":"original","text":"يستطيع الجمل أن يعيش أيامًا طويلة في الصحراء دون أن يشرب، لا لأنه يخزّن الماء في سنامه كما يُشاع، فالسنام مخزن للدهن الذي يتحوّل إلى طاقة عند الحاجة. وسرّ صبره على العطش أنه يقتصد في فقد الماء؛ فهو لا يكاد يتعرّق حتى ترتفع حرارة جسمه كثيرًا، وتمتص كليتاه معظم الماء قبل أن يُطرح. وإذا وجد الماء شرب في دقائق كمية كبيرة تعوّض ما فقده. ولهذه الصفات سمّاه العرب «سفينة الصحراء»."}};
